@Component("deviceCertificate-handler")
@ProcessingGroup("deviceCertificate-processing-group")
public class DeviceCertificateEventHandler {
	
	// core constructor
	DeviceCertificateEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDeviceCertificateEvent
     */
    @EventHandler
    public void handle( CreateDeviceCertificateEvent event) {
        entityManager.persist(new DeviceCertificate(event.getDeviceCertificateId(), event.getSerialNumber(), event.getNotBefore(), event.getNotAfter(), event.getFingerprint(), event.getDevice(), event.getGateway(), event.getCertificateType()));
    }

    /*
     * @param	event UpdateDeviceCertificateEvent
     */
    @EventHandler
    public DeviceCertificate handle( UpdateDeviceCertificateEvent event) {
    	entityManager.merge(new DeviceCertificate(event.getDeviceCertificateId(), event.getSerialNumber(), event.getNotBefore(), event.getNotAfter(), event.getFingerprint(), event.getDevice(), event.getGateway(), event.getCertificateType()));
    }
    
    /*
     * @param	event DeleteDeviceCertificateEvent
     */
    @EventHandler
    public void on( DeleteDeviceCertificateEvent event) {
    	DeviceCertificate entity = new DeviceCertificate();
   
    	// ------------------------------------------
    	// apply the DeviceCertificateId
    	// ------------------------------------------
    	entity.setDeviceCertificateId( event.getDeviceCertificateId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DeviceCertificateRepository deviceCertificateEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DeviceCertificateEventHandler.class.getName());

}
